#include <bits/stdc++.h>
using namespace std;

const int MAXN = 50005;
const int MAXV = 1024; // 2^10
const int INF = 1e9;

int N, M;
int A[MAXN];
int par[MAXN], dep[MAXN], heavy[MAXN], headN[MAXN], sz[MAXN];
vector<int> adj[MAXN];

// 树链剖分第一遍DFS
void dfs1(int u, int p) {
    par[u] = p;
    sz[u] = 1;
    heavy[u] = 0;
    dep[u] = p ? dep[p] + 1 : 0;
    int mx = 0;
    for (int v : adj[u]) {
        if (v == p) continue;
        dfs1(v, u);
        sz[u] += sz[v];
        if (sz[v] > mx) {
            mx = sz[v];
            heavy[u] = v;
        }
    }
}

// 树链剖分第二遍DFS
void dfs2(int u, int h) {
    headN[u] = h;
    if (heavy[u]) dfs2(heavy[u], h);
    for (int v : adj[u]) {
        if (v == par[u] || v == heavy[u]) continue;
        dfs2(v, v);
    }
}

int path_buf[MAXN];
int path_len = 0;

// 提取u到v的路径节点序列
void extractPath(int u, int v) {
    path_len = 0;
    static int l_buf[MAXN], r_buf[MAXN];
    int l_len = 0, r_len = 0;
    
    while (headN[u] != headN[v]) {
        if (dep[headN[u]] > dep[headN[v]]) {
            int h = headN[u];
            for (int x = u; ; x = par[x]) {
                l_buf[l_len++] = x;
                if (x == h) break;
            }
            u = par[h];
        } else {
            int h = headN[v];
            for (int x = v; ; x = par[x]) {
                r_buf[r_len++] = x;
                if (x == h) break;
            }
            v = par[h];
        }
    }
    if (dep[u] <= dep[v]) {
        for (int x = v; ; x = par[x]) {
            r_buf[r_len++] = x;
            if (x == u) break;
        }
    } else {
        for (int x = u; ; x = par[x]) {
            l_buf[l_len++] = x;
            if (x == v) break;
        }
    }
    
    for (int i = 0; i < l_len; i++) path_buf[path_len++] = l_buf[i];
    for (int i = r_len - 1; i >= 0; i--) path_buf[path_len++] = r_buf[i];
}

int cnt[6][MAXV];
int dp_prev[6], dp_curr[6];

int solve(int k) {
    static int S[MAXN];
    S[0] = 0;
    for (int i = 0; i < path_len; i++) {
        S[i + 1] = S[i] ^ A[path_buf[i]];
    }
    
    for (int j = 0; j <= k; j++) {
        dp_prev[j] = -INF;
        for (int v = 0; v < MAXV; v++) cnt[j][v] = -INF;
    }
    
    dp_prev[0] = 0;
    cnt[0][0] = 0;
    
    for (int i = 1; i <= path_len; i++) {
        int si = S[i];
        for (int j = 0; j <= k; j++) {
            dp_curr[j] = dp_prev[j];
            if (j > 0) {
                int best = -INF;
                int* cnt_ptr = cnt[j - 1];
                // 消除分支优化内层循环
                for (int v = 0; v < MAXV; v++) {
                    int val = cnt_ptr[v] + (v ^ si);
                    if (val > best) best = val;
                }
                if (best > dp_curr[j]) dp_curr[j] = best;
                if (dp_curr[j-1] > dp_curr[j]) dp_curr[j] = dp_curr[j-1]; // 允许空段转化（最多 k 段）
            }
        }
        for (int j = 0; j <= k; j++) {
            if (dp_curr[j] > cnt[j][si]) cnt[j][si] = dp_curr[j];
        }
        swap(dp_prev, dp_curr);
    }
    
    int ans = dp_prev[k];
    return ans < 0 ? 0 : ans;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    
    cin >> N >> M;
    for (int i = 1; i <= N; i++) {
        cin >> A[i];
    }
    
    for (int i = 0; i < N - 1; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    
    dfs1(1, 0);
    dfs2(1, 1);
    
    for (int q = 0; q < M; q++) {
        int type;
        cin >> type;
        if (type == 1) {
            int u, x;
            cin >> u >> x;
            A[u] = x;
        } else {
            int u, v, k;
            cin >> u >> v >> k;
            extractPath(u, v);
            cout << solve(k) << "\n";
        }
    }
    
    return 0;
}
